// Maps a time (seconds) in the v1 narration onto the current narration, per scene.
// Scene cues were authored against the v1 (af_heart) WAVs; timewarp.json is generated by
// scripts/make_timewarp.py from sentence boundaries, so cues follow the current voice.
import table from '../timewarp.json';

const W = table as unknown as Record<string, [number, number][]>;

export const warp = (id: string, s: number): number => {
  const pts = W[id];
  if (!pts) return s;
  for (let i = 1; i < pts.length; i++) {
    const [o0, n0] = pts[i - 1];
    const [o1, n1] = pts[i];
    if (s <= o1) return o1 === o0 ? n1 : n0 + ((s - o0) * (n1 - n0)) / (o1 - o0);
  }
  return pts[pts.length - 1][1];
};

/** Warp [start, end, text] chunks (A_helpers format). */
export const warpChunks = <T extends [number, number, string]>(id: string, chunks: T[]): T[] =>
  chunks.map(([a, b, t]) => [warp(id, a), warp(id, b), t] as T);
